"title":"Client analytics via separately authorized read-only links","status":"planned","applicable":true,"dependency_ids":["project:company:future:112:p4:gate"],"gate_ids":[],"acceptance_criteria":["Write a company-specific requirement and business-value hypothesis; classify now/later/optional/exclude with rationale.","Prove permissions, data isolation, failure handling, economic viability and acceptance on domain-specific fixtures.","Do not ship solely because this candidate exists in the exhaustive roadmap."],"evidence_refs":["roadmap/portfolio-future-architecture/companies/112_AUTOMATED_VIDEO_REPURPOSING.md#sha256=6d30b686dd9363640458dcc696affc2f8a3d967bceb0fc62d453f2bb8181aa3b","roadmap/portfolio-future-architecture/five-company-import-2026-11-03/data/AGENCY_TASK_GRAPH.json#project:company:future:112:cap:070"]}],"gates":[{"project_id":"project:company:future:112","roadmap_version":1,"gate_id":"project:company:future:112:p0:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:112","roadmap_version":1,"gate_id":"project:company:future:112:p1:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:112","roadmap_version":1,"gate_id":"project:company:future:112:p2:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:112","roadmap_version":1,"gate_id":"project:company:future:112:p3:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:112","roadmap_version":1,"gate_id":"project:company:future:112:p4:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:112","roadmap_version":1,"gate_id":"project:company:future:112:p5:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:112","roadmap_version":1,"gate_id":"project:company:future:112:p6:approval","satisfied":false,"evidence_refs":[]},{"project_id":"project:company:future:112","roadmap_version":1,"gate_id":"project:company:future:112:p7:approval","satisfied":false,"evidence_refs":[]}]}]$records$::jsonb) loop
  select * into prior from public.command_center_project_profiles where owner_id=v_owner and project_id=item->>'projectId';
  if found then
   if prior.company_id<>item->'profile'->>'company_id' or prior.source_ref<>item->>'sourceRef' or not exists(select 1 from public.command_center_specialist_brains where owner_id=v_owner and brain_key=item->'brain'->>'brain_key' and configuration_ref=item->'brain'->>'configuration_ref') then raise exception 'Company identity/source or partial import conflict: %',item->>'projectId'; end if;
   continue;
  end if;
  if exists(select 1 from public.command_center_project_profiles where owner_id=v_owner and (company_id=item->'profile'->>'company_id' or name::text=item->'profile'->>'name')) or exists(select 1 from public.command_center_canonical_entities where owner_id=v_owner and entity_id=item->>'projectId') or exists(select 1 from public.command_center_specialist_brains where owner_id=v_owner and (brain_key=item->'brain'->>'brain_key' or specialist_id=item->'brain'->>'specialist_id')) then raise exception 'Existing identity collision: %',item->>'projectId'; end if;
  insert into public.command_center_canonical_entities(owner_id,entity_id,project_id,entity_type,payload,content_hash) select x.owner_id,x.entity_id,x.project_id,x.entity_type,x.payload,x.content_hash from jsonb_populate_record(null::public.command_center_canonical_entities,item->'entity'||jsonb_build_object('owner_id',v_owner)) x;
  insert into public.command_center_project_profiles(owner_id,project_id,canonical_entity_id,type_key,company_id,name,mission,lifecycle,status,verification,priority,source_ref,stage,next_action,status_source_refs,status_observed_at) select x.owner_id,x.project_id,x.canonical_entity_id,x.type_key,x.company_id,x.name,x.mission,x.lifecycle,x.status,x.verification,x.priority,x.source_ref,x.stage,x.next_action,x.status_source_refs,x.status_observed_at from jsonb_populate_record(null::public.command_center_project_profiles,item->'profile'||jsonb_build_object('owner_id',v_owner)) x;
  insert into public.command_center_specialist_brains(owner_id,version,enabled,control_plane,domain,subdomains,supported_company_ids,supported_project_ids,supported_work_classes,strengths,weaknesses,method_ids,permission_keys,protected_action_boundaries,data_classes,tool_keys,provider_keys,model_assignments,dependency_version_refs,calibration_score,evaluation_evidence_ids,historical_accuracy,reliability_score,latency_ms,resource_class,cost_class,failure_modes,degraded_modes,fallback_specialist_ids,delegation_targets,learning_eligibility,experiment_status,health,lifecycle,rollback_evidence_id,provenance_evidence_ids,verification_state,revalidated_at,revalidate_after,specialist_id,brain_key,scope,project_id,capabilities,allowed_memory_kinds,configuration_ref,provenance_refs,evaluation_history) select x.owner_id,x.version,x.enabled,x.control_plane,x.domain,x.subdomains,x.supported_company_ids,x.supported_project_ids,x.supported_work_classes,x.strengths,x.weaknesses,x.method_ids,x.permission_keys,x.protected_action_boundaries,x.data_classes,x.tool_keys,x.provider_keys,x.model_assignments,x.dependency_version_refs,x.calibration_score,x.evaluation_evidence_ids,x.historical_accuracy,x.reliability_score,x.latency_ms,x.resource_class,x.cost_class,x.failure_modes,x.degraded_modes,x.fallback_specialist_ids,x.delegation_targets,x.learning_eligibility,x.experiment_status,x.health,x.lifecycle,x.rollback_evidence_id,x.provenance_evidence_ids,x.verification_state,x.revalidated_at,x.revalidate_after,x.specialist_id,x.brain_key,x.scope,x.project_id,x.capabilities,x.allowed_memory_kinds,x.configuration_ref,x.provenance_refs,x.evaluation_history from jsonb_populate_record(null::public.command_center_specialist_brains,item->'brain'||jsonb_build_object('owner_id',v_owner)) x;
  insert into public.command_center_specialist_brain_versions(owner_id,specialist_id,version,snapshot,authority_evidence_ids) select v_owner,b.specialist_id,1,to_jsonb(b)-'owner_id',array['evd_company-'||right(item->>'projectId',3)||'-source-import'] from public.command_center_specialist_brains b where b.owner_id=v_owner and b.brain_key=item->'brain'->>'brain_key';
  insert into public.command_center_project_roadmaps(owner_id,project_id,version,state,structure_verified,denominator_trusted,denominator_evidence_refs,source_ref) select x.owner_id,x.project_id,x.version,x.state,x.structure_verified,x.denominator_trusted,x.denominator_evidence_refs,x.source_ref from jsonb_populate_record(null::public.command_center_project_roadmaps,item->'roadmap'||jsonb_build_object('owner_id',v_owner)) x;
  for unit in select value from jsonb_array_elements(item->'units') loop insert into public.command_center_project_work_units(owner_id,project_id,roadmap_version,work_unit_id,category_id,phase_id,title,status,applicable,dependency_ids,gate_ids,acceptance_criteria,evidence_refs) select x.owner_id,x.project_id,x.roadmap_version,x.work_unit_id,x.category_id,x.phase_id,x.title,x.status,x.applicable,x.dependency_ids,x.gate_ids,x.acceptance_criteria,x.evidence_refs from jsonb_populate_record(null::public.command_center_project_work_units,unit||jsonb_build_object('owner_id',v_owner)) x; end loop;
  for gate in select value from jsonb_array_elements(item->'gates') loop insert into public.command_center_project_roadmap_gates(owner_id,project_id,roadmap_version,gate_id,satisfied,evidence_refs) select x.owner_id,x.project_id,x.roadmap_version,x.gate_id,x.satisfied,x.evidence_refs from jsonb_populate_record(null::public.command_center_project_roadmap_gates,gate||jsonb_build_object('owner_id',v_owner)) x; end loop;
  perform command_center_private.c5_assert_roadmap_integrity(v_owner,item->>'projectId',1);
  update public.command_center_project_roadmaps set structure_verified=true where owner_id=v_owner and project_id=item->>'projectId' and version=1;
  insert into public.command_center_project_checkpoints(owner_id,project_id,roadmap_version,exact_next_work_unit_id,blocker,required_environment,owner_action,verification_method,evidence_refs,resume_state_hash,created_at) select x.owner_id,x.project_id,x.roadmap_version,x.exact_next_work_unit_id,x.blocker,x.required_environment,x.owner_action,x.verification_method,x.evidence_refs,x.resume_state_hash,x.created_at from jsonb_populate_record(null::public.command_center_project_checkpoints,item->'checkpoint'||jsonb_build_object('owner_id',v_owner)) x;
 end loop;
end $import$;
commit;
